solution.list_ops.zig:
const std = @import("std");

pub fn append(comptime T: type, allocator: std.mem.Allocator, first: []const T, second: []const T) ![]T {
    const out = try allocator.alloc(T,first.len+second.len);
    @memcpy(out[0..first.len],first); @memcpy(out[first.len..],second); return out;
}
pub fn concat(comptime T: type, allocator: std.mem.Allocator, lists: []const []const T) ![]T {
    var size: usize = 0; for (lists) |list| size += list.len;
    const out = try allocator.alloc(T,size); var offset: usize=0;
    for (lists) |list| { for (list) |item| { out[offset]=item; offset+=1; } }
    return out;
}
pub fn filter(comptime T: type, allocator: std.mem.Allocator, list: []const T, predicate: fn(T) bool) ![]T {
    var out = std.array_list.Managed(T).init(allocator); errdefer out.deinit();
    for (list) |item| if (predicate(item)) { try out.append(item); };
    return out.toOwnedSlice();
}
pub fn length(comptime T: type, list: []const T) usize { var n: usize=0; for (list) |_| n+=1; return n; }
pub fn map(comptime T: type, comptime U: type, allocator: std.mem.Allocator, list: []const T, operation: fn(T) U) ![]U {
    const out=try allocator.alloc(U,list.len); for (list,0..) |v,i| out[i]=operation(v); return out;
}
pub fn foldl(comptime T: type, comptime U: type, list: []const T, initial: U, operation: fn(U,T) U) U {
    var result=initial; for (list) |item| result=operation(result,item); return result;
}
pub fn foldr(comptime T: type, comptime U: type, list: []const T, initial: U, operation: fn(T,U) U) U {
    var result=initial; var i=list.len; while(i>0) { i-=1; result=operation(list[i],result); } return result;
}
pub fn reverse(comptime T: type, allocator: std.mem.Allocator, list: []const T) ![]T {
    const out=try allocator.alloc(T,list.len); for(list,0..) |v,i| out[list.len-1-i]=v; return out;
}

tests.test_list_ops.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("list_ops.zig");

fn odd(v:i32) bool {return @mod(v,2)==1;}
fn twice(v:i32) i32 {return 2*v;}
fn subtract(x:i32,y:i32) i32 {return x-y;}
test "all list operations, empty inputs and fold direction" {
    const joined=try m.append(i32,a,&.{1,2},&.{3}); defer a.free(joined); try t.expectEqualSlices(i32,&.{1,2,3},joined);
    const lists = [_][]const i32{&.{1,2},&.{},&.{3,4}};
    const flat=try m.concat(i32,a,&lists); defer a.free(flat); try t.expectEqualSlices(i32,&.{1,2,3,4},flat);
    const filtered=try m.filter(i32,a,flat,odd); defer a.free(filtered); try t.expectEqualSlices(i32,&.{1,3},filtered);
    try t.expectEqual(@as(usize,4),m.length(i32,flat)); try t.expectEqual(@as(usize,0),m.length(i32,&.{}));
    const mapped=try m.map(i32,i32,a,flat,twice); defer a.free(mapped); try t.expectEqualSlices(i32,&.{2,4,6,8},mapped);
    try t.expectEqual(@as(i32,-10),m.foldl(i32,i32,flat,0,subtract));
    try t.expectEqual(@as(i32,-2),m.foldr(i32,i32,flat,0,subtract));
    try t.expectEqual(@as(i32,7),m.foldr(i32,i32,&.{},7,subtract));
    const reversed=try m.reverse(i32,a,flat); defer a.free(reversed); try t.expectEqualSlices(i32,&.{4,3,2,1},reversed);
    const empty=try m.concat(i32,a,&.{}); defer a.free(empty); try t.expectEqual(@as(usize,0),empty.len);
}

